INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',8,'{"_type":"chat:Message","id":"8641420749:12","threadId":"telegram:8641420749","text":"Tu penses quoi de mes activités des 6 derniers jours ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Tu penses quoi de mes activités des 6 derniers jours ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":55,"offset":54}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":55,"offset":54}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":55,"offset":54}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-15T19:13:20.000Z","edited":false},"attachments":[],"isMention":false}',1782155598515);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',9,'{"_type":"chat:Message","id":"8641420749:17","threadId":"telegram:8641420749","text":"Voici mon historique d''entraînement.\n\nJ''ai commencé avec un coach route classique en juillet 2025, à peu près 10 semaines avant mon premier Marseille-Napoli, qui était en septembre, la première semaine d''octobre 2025. Après l''événement l''entraînement est devenu plus routinier et moi, ce truc, a été structuré avec des phases.\n\nJ''ai fait plusieurs brevets :\n- J''ai fait un brevet de 336 km en février peut-être ou en mars 2026\n- J''ai fait Porto-Lisbonne, 360 km, le 24 avril 2026\n- J''ai aussi fait un brevet de 200 km en décembre 2025.\n\n\nJe veux que tu analyses mes données Strava depuis juillet 2025 pour voir l''évolution de mon volume et de ma forme. J''avais fait un test lactate début août 2025 ou fin juillet et je n''ai refait un en début d''année, vers janvier, où mes zones d''entraînement, mes zones cardiaques d''entraînement, ont évolué et elles étaient bien mieux en janvier.\n\nJe veux aussi que tu identifies les métriques que on va suivre ensemble et que tu m''expliques pourquoi ce sont les métriques qui font sens","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Voici mon historique d''entraînement.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":37,"offset":36}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":37,"offset":36}}},{"type":"paragraph","children":[{"type":"text","value":"J''ai commencé avec un coach route classique en juillet 2025, à peu près 10 semaines avant mon premier Marseille-Napoli, qui était en septembre, la première semaine d''octobre 2025. Après l''événement l''entraînement est devenu plus routinier et moi, ce truc, a été structuré avec des phases.","position":{"start":{"line":3,"column":1,"offset":38},"end":{"line":3,"column":289,"offset":326}}}],"position":{"start":{"line":3,"column":1,"offset":38},"end":{"line":3,"column":289,"offset":326}}},{"type":"paragraph","children":[{"type":"text","value":"J''ai fait plusieurs brevets :","position":{"start":{"line":5,"column":1,"offset":328},"end":{"line":5,"column":30,"offset":357}}}],"position":{"start":{"line":5,"column":1,"offset":328},"end":{"line":5,"column":30,"offset":357}}},{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"J''ai fait un brevet de 336 km en février peut-être ou en mars 2026","position":{"start":{"line":6,"column":3,"offset":360},"end":{"line":6,"column":69,"offset":426}}}],"position":{"start":{"line":6,"column":3,"offset":360},"end":{"line":6,"column":69,"offset":426}}}],"position":{"start":{"line":6,"column":1,"offset":358},"end":{"line":6,"column":69,"offset":426}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"J''ai fait Porto-Lisbonne, 360 km, le 24 avril 2026","position":{"start":{"line":7,"column":3,"offset":429},"end":{"line":7,"column":53,"offset":479}}}],"position":{"start":{"line":7,"column":3,"offset":429},"end":{"line":7,"column":53,"offset":479}}}],"position":{"start":{"line":7,"column":1,"offset":427},"end":{"line":7,"column":53,"offset":479}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"J''ai aussi fait un brevet de 200 km en décembre 2025.","position":{"start":{"line":8,"column":3,"offset":482},"end":{"line":8,"column":56,"offset":535}}}],"position":{"start":{"line":8,"column":3,"offset":482},"end":{"line":8,"column":56,"offset":535}}}],"position":{"start":{"line":8,"column":1,"offset":480},"end":{"line":8,"column":56,"offset":535}}}],"position":{"start":{"line":6,"column":1,"offset":358},"end":{"line":8,"column":56,"offset":535}}},{"type":"paragraph","children":[{"type":"text","value":"Je veux que tu analyses mes données Strava depuis juillet 2025 pour voir l''évolution de mon volume et de ma forme. J''avais fait un test lactate début août 2025 ou fin juillet et je n''ai refait un en début d''année, vers janvier, où mes zones d''entraînement, mes zones cardiaques d''entraînement, ont évolué et elles étaient bien mieux en janvier.","position":{"start":{"line":11,"column":1,"offset":538},"end":{"line":11,"column":345,"offset":882}}}],"position":{"start":{"line":11,"column":1,"offset":538},"end":{"line":11,"column":345,"offset":882}}},{"type":"paragraph","children":[{"type":"text","value":"Je veux aussi que tu identifies les métriques que on va suivre ensemble et que tu m''expliques pourquoi ce sont les métriques qui font sens","position":{"start":{"line":13,"column":1,"offset":884},"end":{"line":13,"column":139,"offset":1022}}}],"position":{"start":{"line":13,"column":1,"offset":884},"end":{"line":13,"column":139,"offset":1022}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":13,"column":139,"offset":1022}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-15T20:36:43.000Z","edited":false},"attachments":[],"isMention":false}',1782160603067);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',10,'{"_type":"chat:Message","id":"8641420749:23","threadId":"telegram:8641420749","text":"Je vais aussi te partager mes défis actuels et l''état dans lequel je me trouve. \n\nJ''ai toujours eu des challenges de genoux qui s''inflamment. En fait, j''ai ce qu''on appelle un syndrome feromo patelaire (syndrome rotulien), c''est-à-dire que la rotule n''est pas aussi bien centrée qu''elle le devrait. Du coup, je peux facilement me retrouver dans une situation où le tendon frotte là où il ne devrait pas frotter, donc ça peut s''inflammer. De manière plus ou moins forte, Ça s''est lancé il y a à peu près une dizaine d''années. \n\nMais là, l''année dernière, depuis que j''ai pris l''entraînement très fort, ça m''a lancé sur Marseille-Napoli le deuxième jour après le col du Turini et sur le genou droit, et j''ai réussi à le gérer. il me restait encore 1000 kilomètres. C''était déjà inflammé. En prenant de l''ibuprofène et en gérant dès que je suis en danseuse, donc debout, ça me fait beaucoup moins mal. Donc j''ai réussi à gérer ça. \n\nEnsuite, j''ai fait une pause d''à peu près 5-6 semaines et j''ai vu un très bon kiné-ostéopathe et un très bon coach personal trainer qui m''a fait faire plein d''exercices qui ont vraiment été super. Voilà, donc j''ai eu une routine assez bonne de core strength, de renforcement du genou, mais aussi du dos, parce qu''au dos, j''ai un léger ligament qui fonctionne moins bien au niveau du bas du dos. Donc, en fait, il faut que je fasse du renforcement. \n\nSauf que malheureusement, depuis janvier/février, j''ai eu beaucoup plus de mal à avoir de la discipline là-dessus. Et j''ai malgré tout préparé Porto-Lisbonne, mais aussi Paris-Marseille, qui était 850 km en 72 heures. En fait, j''ai mon genou gauche, cette fois-ci, qui s''est inflammé très vite. Et donc, j''ai dû DNF le premier jour, enfin la première nuit, après avoir pédalé 7/8 heures. \n\nMais en fait, c''est parce que j''avais été malade les quatre semaines avant. Et les dix derniers jours, je n''ai pas du tout pédalé, je me suis concentré complètement sur récupérer de mon rhume. Donc, en fait, je n''ai fait aucun effort et tout d''un coup, après 10 ou 15 jours sans faire aucun effort, j''ai fait 160 km de nuit, sachant qu''il fallait que j''en fasse 380. Du coup, mon genou a chauffé très très vite. \n\nEt donc, après, à la fin de cette journée, il a désenflammé et j''ai pu finalement reprendre le vélo le lendemain. J''ai pu faire 200 km ce jour-là et le lendemain, à nouveau 200 km avec le mont Ventoux au milieu. J''ai eu un peu mal au genou sur la dernière partie, sur les 50 derniers kilomètres, mais c''était faisable. \n\nDonc voilà, et en fait, depuis ça, qui était là le 22 mai, je n''ai pas totalement pris les choses en main. J''ai un peu réduit le volume, mais j''ai continué à pédaler, je n''ai pas fait d''exercice de renfo. Je sens que mon genou n’est pas récupéré a 100%. Et donc là, j''ai décidé qu''il fallait que je fasse au moins trois semaines où je fais beaucoup moins de vélo, je fais beaucoup plus de natation et je fais les exercices, les mêmes exercices que j''avais faits après Marseille-Napoli pour mes genoux, histoire de récupérer à 100%. \n\nJe vais voir mon ostéopathe le 25 juin, dans dix jours. Donc voilà, ça ce sera la prochaine phase, au moins deux trois semaines, et ensuite, après ça, il faut qu''on mette en place le plan d''entraînement jusqu''à Marseille-Napoli, qui sera fin septembre.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je vais aussi te partager mes défis actuels et l''état dans lequel je me trouve.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":80,"offset":79}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":81,"offset":80}}},{"type":"paragraph","children":[{"type":"text","value":"J''ai toujours eu des challenges de genoux qui s''inflamment. En fait, j''ai ce qu''on appelle un syndrome feromo patelaire (syndrome rotulien), c''est-à-dire que la rotule n''est pas aussi bien centrée qu''elle le devrait. Du coup, je peux facilement me retrouver dans une situation où le tendon frotte là où il ne devrait pas frotter, donc ça peut s''inflammer. De manière plus ou moins forte, Ça s''est lancé il y a à peu près une dizaine d''années.","position":{"start":{"line":3,"column":1,"offset":82},"end":{"line":3,"column":443,"offset":524}}}],"position":{"start":{"line":3,"column":1,"offset":82},"end":{"line":3,"column":444,"offset":525}}},{"type":"paragraph","children":[{"type":"text","value":"Mais là, l''année dernière, depuis que j''ai pris l''entraînement très fort, ça m''a lancé sur Marseille-Napoli le deuxième jour après le col du Turini et sur le genou droit, et j''ai réussi à le gérer. il me restait encore 1000 kilomètres. C''était déjà inflammé. En prenant de l''ibuprofène et en gérant dès que je suis en danseuse, donc debout, ça me fait beaucoup moins mal. Donc j''ai réussi à gérer ça.","position":{"start":{"line":5,"column":1,"offset":527},"end":{"line":5,"column":401,"offset":927}}}],"position":{"start":{"line":5,"column":1,"offset":527},"end":{"line":5,"column":402,"offset":928}}},{"type":"paragraph","children":[{"type":"text","value":"Ensuite, j''ai fait une pause d''à peu près 5-6 semaines et j''ai vu un très bon kiné-ostéopathe et un très bon coach personal trainer qui m''a fait faire plein d''exercices qui ont vraiment été super. Voilà, donc j''ai eu une routine assez bonne de core strength, de renforcement du genou, mais aussi du dos, parce qu''au dos, j''ai un léger ligament qui fonctionne moins bien au niveau du bas du dos. Donc, en fait, il faut que je fasse du renforcement.","position":{"start":{"line":7,"column":1,"offset":930},"end":{"line":7,"column":448,"offset":1377}}}],"position":{"start":{"line":7,"column":1,"offset":930},"end":{"line":7,"column":449,"offset":1378}}},{"type":"paragraph","children":[{"type":"text","value":"Sauf que malheureusement, depuis janvier/février, j''ai eu beaucoup plus de mal à avoir de la discipline là-dessus. Et j''ai malgré tout préparé Porto-Lisbonne, mais aussi Paris-Marseille, qui était 850 km en 72 heures. En fait, j''ai mon genou gauche, cette fois-ci, qui s''est inflammé très vite. Et donc, j''ai dû DNF le premier jour, enfin la première nuit, après avoir pédalé 7/8 heures.","position":{"start":{"line":9,"column":1,"offset":1380},"end":{"line":9,"column":388,"offset":1767}}}],"position":{"start":{"line":9,"column":1,"offset":1380},"end":{"line":9,"column":389,"offset":1768}}},{"type":"paragraph","children":[{"type":"text","value":"Mais en fait, c''est parce que j''avais été malade les quatre semaines avant. Et les dix derniers jours, je n''ai pas du tout pédalé, je me suis concentré complètement sur récupérer de mon rhume. Donc, en fait, je n''ai fait aucun effort et tout d''un coup, après 10 ou 15 jours sans faire aucun effort, j''ai fait 160 km de nuit, sachant qu''il fallait que j''en fasse 380. Du coup, mon genou a chauffé très très vite.","position":{"start":{"line":11,"column":1,"offset":1770},"end":{"line":11,"column":412,"offset":2181}}}],"position":{"start":{"line":11,"column":1,"offset":1770},"end":{"line":11,"column":413,"offset":2182}}},{"type":"paragraph","children":[{"type":"text","value":"Et donc, après, à la fin de cette journée, il a désenflammé et j''ai pu finalement reprendre le vélo le lendemain. J''ai pu faire 200 km ce jour-là et le lendemain, à nouveau 200 km avec le mont Ventoux au milieu. J''ai eu un peu mal au genou sur la dernière partie, sur les 50 derniers kilomètres, mais c''était faisable.","position":{"start":{"line":13,"column":1,"offset":2184},"end":{"line":13,"column":319,"offset":2502}}}],"position":{"start":{"line":13,"column":1,"offset":2184},"end":{"line":13,"column":320,"offset":2503}}},{"type":"paragraph","children":[{"type":"text","value":"Donc voilà, et en fait, depuis ça, qui était là le 22 mai, je n''ai pas totalement pris les choses en main. J''ai un peu réduit le volume, mais j''ai continué à pédaler, je n''ai pas fait d''exercice de renfo. Je sens que mon genou n’est pas récupéré a 100%. Et donc là, j''ai décidé qu''il fallait que je fasse au moins trois semaines où je fais beaucoup moins de vélo, je fais beaucoup plus de natation et je fais les exercices, les mêmes exercices que j''avais faits après Marseille-Napoli pour mes genoux, histoire de récupérer à 100%.","position":{"start":{"line":15,"column":1,"offset":2505},"end":{"line":15,"column":532,"offset":3036}}}],"position":{"start":{"line":15,"column":1,"offset":2505},"end":{"line":15,"column":533,"offset":3037}}},{"type":"paragraph","children":[{"type":"text","value":"Je vais voir mon ostéopathe le 25 juin, dans dix jours. Donc voilà, ça ce sera la prochaine phase, au moins deux trois semaines, et ensuite, après ça, il faut qu''on mette en place le plan d''entraînement jusqu''à Marseille-Napoli, qui sera fin septembre.","position":{"start":{"line":17,"column":1,"offset":3039},"end":{"line":17,"column":253,"offset":3291}}}],"position":{"start":{"line":17,"column":1,"offset":3039},"end":{"line":17,"column":253,"offset":3291}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":17,"column":253,"offset":3291}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-15T20:48:10.000Z","edited":false},"attachments":[],"isMention":false}',1782161289893);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',11,'{"_type":"chat:Message","id":"8641420749:26","threadId":"telegram:8641420749","text":"More info:\n• for Marseille Napoli this year, I will be with 2 friends who are less experienced than me, my goal is to have the best experience with them as possible, I''m not seeking any sort of performance or timing. I want to finish on Friday end of the day soit 230km par jour minimum et un total de 17950m de D+. I want to feel good and have no knee pain. Zero knee pain is my main objective.\n• regarding availability for training, I''m fully available from June 15 (today) to July 16.\n• between July 16 and July 24, I will be doing a hike in the Alps with 15 to 20km per day and between 1000 and 2000m de D+ per day.\n• then July 25 to Aug 9 I will be fully available for training\n• then Aug 10 to 19 also available but maybe less hours per day (not sure yet if I''ll have my bike or another bike, I''ll be on vacation in Annecy)\n• then Aug 20 to Sept 27 fully available\n• Marseill Napoli starts on Sunday Sept 27","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"More info:\n• for Marseille Napoli this year, I will be with 2 friends who are less experienced than me, my goal is to have the best experience with them as possible, I''m not seeking any sort of performance or timing. I want to finish on Friday end of the day soit 230km par jour minimum et un total de 17950m de D+. I want to feel good and have no knee pain. Zero knee pain is my main objective.\n• regarding availability for training, I''m fully available from June 15 (today) to July 16.\n• between July 16 and July 24, I will be doing a hike in the Alps with 15 to 20km per day and between 1000 and 2000m de D+ per day.\n• then July 25 to Aug 9 I will be fully available for training\n• then Aug 10 to 19 also available but maybe less hours per day (not sure yet if I''ll have my bike or another bike, I''ll be on vacation in Annecy)\n• then Aug 20 to Sept 27 fully available\n• Marseill Napoli starts on Sunday Sept 27","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":8,"column":43,"offset":913}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":8,"column":43,"offset":913}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":8,"column":43,"offset":913}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-15T21:00:50.000Z","edited":false},"attachments":[],"isMention":false}',1782162048320);
