4,"offset":157},"end":{"line":4,"column":40,"offset":193}}}],"position":{"start":{"line":4,"column":4,"offset":157},"end":{"line":4,"column":40,"offset":193}}}],"position":{"start":{"line":4,"column":1,"offset":154},"end":{"line":4,"column":40,"offset":193}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"side plank with leg raise and feet on bench (2x10sec each side)\nand to others for which I will send you videos","position":{"start":{"line":5,"column":4,"offset":197},"end":{"line":6,"column":47,"offset":307}}}],"position":{"start":{"line":5,"column":4,"offset":197},"end":{"line":6,"column":47,"offset":307}}}],"position":{"start":{"line":5,"column":1,"offset":194},"end":{"line":6,"column":47,"offset":307}}}],"position":{"start":{"line":2,"column":1,"offset":69},"end":{"line":6,"column":47,"offset":307}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":6,"column":47,"offset":307}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-15T21:55:47.000Z","edited":false},"attachments":[],"isMention":false}',1782165347407);
