INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',25,'{"_type":"chat:Message","id":"8641420749:62","threadId":"telegram:8641420749","text":"Ok on continue demain : macro plan + daily plan jusqu’a dimanche. Je commence demain midi.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Ok on continue demain : macro plan + daily plan jusqu’a dimanche. Je commence demain midi.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":91,"offset":90}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":91,"offset":90}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":91,"offset":90}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-15T22:43:59.000Z","edited":false},"attachments":[],"isMention":false}',1782168236558);
