INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',342,'{"_type":"chat:Message","id":"-5124234082:2179","threadId":"telegram:-5124234082","text":"Voici les menu du dejeuner des enfants, je veux que tu en tiennes compte dans le menu du soir, pour eviter les repetitions. Je veux aussi que tu m’informes de leur menu du dejeuner tous les matins dans le checkin du matin.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Voici les menu du dejeuner des enfants, je veux que tu en tiennes compte dans le menu du soir, pour eviter les repetitions. Je veux aussi que tu m’informes de leur menu du dejeuner tous les matins dans le checkin du matin.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":223,"offset":222}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":223,"offset":222}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":223,"offset":222}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-16T07:52:19.000Z","edited":false},"attachments":[{"type":"image","size":190158,"width":1920,"height":2560}],"isMention":false}',1782201138905);
