INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',54,'{"_type":"chat:Message","id":"8641420749:149","threadId":"telegram:8641420749","text":"Demain je ne suis pas sur de pouvoir placer le vélo dans l’agenda, je ferai tout pour placer le renfo. Je peux peut être le deplacer a samedi matin. Et la course à pied est-ce vraiment raisonnable tant que je suis en recup du genou ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Demain je ne suis pas sur de pouvoir placer le vélo dans l’agenda, je ferai tout pour placer le renfo. Je peux peut être le deplacer a samedi matin. Et la course à pied est-ce vraiment raisonnable tant que je suis en recup du genou ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":234,"offset":233}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":234,"offset":233}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":234,"offset":233}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-18T22:47:47.000Z","edited":false},"attachments":[],"isMention":false}',1782427666949);
