INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',367,'{"_type":"chat:Message","id":"-5124234082:2273","threadId":"telegram:-5124234082","text":"https://www.cuerpomente.com/recetas-veganas/platos/ensaladas-mediterraneas-toque-exotico-no-hinchan-te-solucionan-cenas-verano_13527\n\nPepa dame la lista de ingredientes para estas recetas","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"link","title":null,"url":"https://www.cuerpomente.com/recetas-veganas/platos/ensaladas-mediterraneas-toque-exotico-no-hinchan-te-solucionan-cenas-verano_13527","children":[{"type":"text","value":"https://www.cuerpomente.com/recetas-veganas/platos/ensaladas-mediterraneas-toque-exotico-no-hinchan-te-solucionan-cenas-verano_13527","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":133,"offset":132}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":133,"offset":132}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":133,"offset":132}}},{"type":"paragraph","children":[{"type":"text","value":"Pepa dame la lista de ingredientes para estas recetas","position":{"start":{"line":3,"column":1,"offset":134},"end":{"line":3,"column":54,"offset":187}}}],"position":{"start":{"line":3,"column":1,"offset":134},"end":{"line":3,"column":54,"offset":187}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":54,"offset":187}}},"raw":null,"author":{"userId":"8786812707","userName":"Lola","fullName":"Lola Daroca","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-21T16:55:20.000Z","edited":false},"attachments":[],"isMention":false}',1782665719368);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',368,'{"_type":"chat:Message","id":"-5124234082:2276","threadId":"telegram:-5124234082","text":"**Verduras y hojas verdes**\n\n3 limones (usarás 2½ aprox.)\n1 lima\n2 tomates de Barbastro grandes (o 3 pequeños)\n1 bandeja de tomates cherry (250 g)\n1 pepino\n1 zanahoria grande\n1 remolacha pequeña\n1 pimiento rojo\n3 endivias grandes\n2 cogollos de Tudela\n1 lechuga hoja de roble\n1 bolsa de canónigos (100 g)\n1 bolsa pequeña de rúcula (100 g)\n1 aguacate\n1 mango grande\n1 bandeja de germinados de rabanito\n1 manojo de perejil\n1 manojo de menta fresca\n1 trocito de jengibre fresco\n1 guindilla fresca\n\n**Proteínas vegetales y legumbres**\n\n1 bote de garbanzos cocidos (400 g netos aprox.)\n1 paquete de tofu firme (250–300 g)\n1 paquete de tempeh (250 g)\n1 bolsa de edamame congelado (300–400 g)\n1 bote de altramuces (al menos 100 g escurridos)\n\n**Cereales y pasta**\n\n100 g de quinoa\n100 g de arroz basmati\n1 paquete de pasta de lentejas rojas (250 g)\n\n**Frutos secos y semillas**\n\nComprar bolsas pequeñas de 100 g suele ser lo más práctico:\n\nSemillas de girasol (100 g)\nPipas de calabaza (100 g)\nCacahuetes tostados (100 g)\nAlmendras tostadas (100 g)\nPiñones (50 g)\n\n**Conservas y productos especiales**\n\n1 lata pequeña de maíz dulce\n1 tarro pequeño de aceitunas Kalamata\n1 paquete de alga wakame seca\n1 bote pequeño de tahini\n1 bote pequeño de miso blanco\n1 botella de tamari\n\n**Lácteos y huevos**\n\n2 huevos\n1 cuña pequeña de parmesano","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Verduras y hojas verdes","position":{"start":{"line":1,"column":3,"offset":2},"end":{"line":1,"column":26,"offset":25}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":28,"offset":27}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":28,"offset":27}}},{"type":"paragraph","children":[{"type":"text","value":"3 limones (usarás 2½ aprox.)\n1 lima\n2 tomates de Barbastro grandes (o 3 pequeños)\n1 bandeja de tomates cherry (250 g)\n1 pepino\n1 zanahoria grande\n1 remolacha pequeña\n1 pimiento rojo\n3 endivias grandes\n2 cogollos de Tudela\n1 lechuga hoja de roble\n1 bolsa de canónigos (100 g)\n1 bolsa pequeña de rúcula (100 g)\n1 aguacate\n1 mango grande\n1 bandeja de germinados de rabanito\n1 manojo de perejil\n1 manojo de menta fresca\n1 trocito de jengibre fresco\n1 guindilla fresca","position":{"start":{"line":3,"column":1,"offset":29},"end":{"line":22,"column":19,"offset":492}}}],"position":{"start":{"line":3,"column":1,"offset":29},"end":{"line":22,"column":19,"offset":492}}},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Proteínas vegetales y legumbres","position":{"start":{"line":24,"column":3,"offset":496},"end":{"line":24,"column":34,"offset":527}}}],"position":{"start":{"line":24,"column":1,"offset":494},"end":{"line":24,"column":36,"offset":529}}}],"position":{"start":{"line":24,"column":1,"offset":494},"end":{"line":24,"column":36,"offset":529}}},{"type":"paragraph","children":[{"type":"text","value":"1 bote de garbanzos cocidos (400 g netos aprox.)\n1 paquete de tofu firme (250–300 g)\n1 paquete de tempeh (250 g)\n1 bolsa de edamame congelado (300–400 g)\n1 bote de altramuces (al menos 100 g escurridos)","position":{"start":{"line":26,"column":1,"offset":531},"end":{"line":30,"column":49,"offset":733}}}],"position":{"start":{"line":26,"column":1,"offset":531},"end":{"line":30,"column":49,"offset":733}}},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Cereales y pasta","position":{"start":{"line":32,"column":3,"offset":737},"end":{"line":32,"column":19,"offset":753}}}],"position":{"start":{"line":32,"column":1,"offset":735},"end":{"line":32,"column":21,"offset":755}}}],"position":{"start":{"line":32,"column":1,"offset":735},"end":{"line":32,"column":21,"offset":755}}},{"type":"paragraph","children":[{"type":"text","value":"100 g de quinoa\n100 g de arroz basmati\n1 paquete de pasta de lentejas rojas (250 g)","position":{"start":{"line":34,"column":1,"offset":757},"end":{"line":36,"column":45,"offset":840}}}],"position":{"start":{"line":34,"column":1,"offset":757},"end":{"line":36,"column":45,"offset":840}}},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Frutos secos y semillas","position":{"start":{"line":38,"column":3,"offset":844},"end":{"line":38,"column":26,"offset":867}}}],"position":{"start":{"line":38,"column":1,"offset":842},"end":{"line":38,"column":28,"offset":869}}}],"position":{"start":{"line":38,"column":1,"offset":842},"end":{"line":38,"column":28,"offset":869}}},{"type":"paragraph","children":[{"type":"text","value":"Comprar bolsas pequeñas de 100 g suele ser lo más práctico:","position":{"start":{"line":40,"column":1,"offset":871},"end":{"line":40,"column":60,"offset":930}}}],"position":{"start":{"line":40,"column":1,"offset":871},"end":{"line":40,"column":60,"offset":930}}},{"type":"paragraph","children":[{"type":"text","value":"Semillas de girasol (100 g)\nPipas de calabaza (100 g)\nCacahuetes tostados (100 g)\nAlmendras tostadas (100 g)\nPiñones (50 g)","position":{"start":{"line":42,"column":1,"offset":932},"end":{"line":46,"column":15,"offset":1055}}}],"position":{"start":{"line":42,"column":1,"offset":932},"end":{"line":46,"column":15,"offset":1055}}},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Conservas y productos especiales","position":{"start":{"line":48,"column":3,"offset":1059},"end":{"line":48,"column":35,"offset":1091}}}],"position":{"start":{"line":48,"column":1,"offset":1057},"end":{"line":48,"column":37,"offset":1093}}}],"position":{"start":{"line":48,"column":1,"offset":1057},"end":{"line":48,"column":37,"offset":1093}}},{"type":"paragraph","children":[{"type":"text","value":"1 lata pequeña d