INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',75,'{"_type":"chat:Message","id":"8641420749:215","threadId":"telegram:8641420749","text":"Il faut qu’on adapte car je vais etre en business trip à Stuttgart de lundi à jeudi :\n- aujourd’hui, pas pu pedaler mais je vais sortir marcher 30min, ça devrait me faire du bien qu’en penses-tu ?\n- demain lundi, arrivée à 17h10 à l’aeroport. Je peux etre a la salle de sport de l’hotel a 18h pendant max 2h\n- mardi, 2-3h libre l’apres midi a la salle de sport de l’hotel\n- mercredi 1h dispo le matin a la salle de sport\n- jeudi je rentre tout juste pour l’horaire de la piscine\n- vendredi je travaille pas, consult osteo/fisio a 8h30","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Il faut qu’on adapte car je vais etre en business trip à Stuttgart de lundi à jeudi :","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":86,"offset":85}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":86,"offset":85}}},{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"aujourd’hui, pas pu pedaler mais je vais sortir marcher 30min, ça devrait me faire du bien qu’en penses-tu ?","position":{"start":{"line":2,"column":3,"offset":88},"end":{"line":2,"column":111,"offset":196}}}],"position":{"start":{"line":2,"column":3,"offset":88},"end":{"line":2,"column":111,"offset":196}}}],"position":{"start":{"line":2,"column":1,"offset":86},"end":{"line":2,"column":111,"offset":196}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"demain lundi, arrivée à 17h10 à l’aeroport. Je peux etre a la salle de sport de l’hotel a 18h pendant max 2h","position":{"start":{"line":3,"column":3,"offset":199},"end":{"line":3,"column":111,"offset":307}}}]